13	//
14	// PRISM RTU intrinsics — ISA ABI v2 (scope-partitioned window trace, with
15	// callback-window additions).
16	//
17	// The RTU ISA is the v2 window ABI (CUSTOM1, funct3 = 6/7). The callback-side
18	// single-slot helpers below ride funct3 = 6 (funct2 selects: 0=cb_ret, 1=SETW
19	// write, 2=GETWF FP read, 3=GETW GP read); the per-trace path (vx_rt_wtrace /
20	// vx_rt_wait, further down) rides funct3 = 7.
21	
22	#pragma once
23	
24	#include <vx_intrinsics.h>
25	#include <vx_gfx_window.h>   // vx_gfx_set (SETW) / vx_gfx_get / vx_gfx_get_after (GETW)
26	#include <VX_types.h>
27	#include <stdint.h>
28	
29	#ifdef __cplusplus
30	extern "C" {
31	#endif
32	
33	// The register-window primitives — vx_gfx_set (SETW) and vx_gfx_get /
34	// vx_gfx_get_after (GETW) — live in <vx_gfx_window.h>, the shared substrate the
35	// RTU and graphics both build on. A callback dispatcher stages a slot (e.g. the
36	// IS-computed hit_t) with vx_gfx_set before vx_rt_cb_ret; ordinary kernel code
37	// reads a non-standard hit attribute AFTER vx_rt_wait with
38	// vx_gfx_get_after(slot, status), which rides the wait's status word as rs1 to
39	// chain the scoreboard dep onto the wait's writeback (the trace does not retire
40	// until its TERMINAL drains, so the read observes post-TERMINAL attributes).
41	
42	// vx_rt_cb_ret — release the lane's parked context in the RTU
43	// with one of VX_RT_CB_{ACCEPT,IGNORE,TERMINATE}. The callback dispatcher
44	// (mtvec-registered) calls this once it has decided the candidate hit's
45	// fate, then exits via `mret` to resume the post-vx_rt_wait PC. The
46	// dispatcher's tmask was narrowed at trap entry to only-yielded-lanes and
47	// is restored by `mret` from the saved tmask CSR.
48	//
49	// EXT2 / funct3=6 / sub-op=0 / R-type. rs1 = action; no rd.
50	#define vx_rt_cb_ret(action) \
51	  __asm__ volatile (".insn r %0, 6, 0, x0, %1, x0" \
52	      :: "i"(RISCV_CUSTOM1), "r"(action))
53	
54	// Mark a function as the RTU callback dispatcher. The compiler should emit it
55	// as a normal extern-"C" function; the dispatcher is responsible for exiting
56	// via `mret` (e.g. by tail-calling a small `mret` stub or finishing with
57	// `vx_rt_cb_ret` + an inline `mret` asm). A no-op attribute today; a future
58	// Mesa codegen pass can lower it into a real attribute (preserve `mret`
59	// epilogue, no caller-save spill).
60	#define VX_RT_CALLBACK_ENTRY __attribute__((used))
61	
62	// `vx_mret()` (in vx_intrinsics.h) is the trap-return primitive an RTU
63	// callback dispatcher uses at its bottom to resume the post-vx_rt_wait PC
64	// and restore the pre-yield tmask.
65	
66	// Convenience float-encoding helper.
67	static inline uint32_t vx_rt_f2u(float f) {
68	  union { float f; uint32_t u; } c;
69	  c.f = f;
70	  return c.u;
71	}
72	
73	// ===========================================================================
74	// ISA ABI v2 — scope-partitioned single-issue trace.
75	// The ~16-op vx_gfx_set/get marshalling collapses to
76	// one trace + one wait. Encoding lives at CUSTOM1 / funct3 = 7:
77	//
78	//   funct2 = 0  vx_rt_wtrace      R-type macro-op; rd = handle, rs1 = lane-packed
79	//                                config, ray window = f0..f7
80	//   funct2 = 1  vx_rt_wait       R-type macro-op; rd = status, rs1 = handle;
81	//                                HW writes t/u/v -> f0..f2, IDs -> t3..t5
82	// ===========================================================================
83	
84	// Per-thread ray geometry — the divergent operand that rides the f0..f7
85	// register window (no marshalling: it is the compiler's register allocation).
86	typedef struct {
87	  float origin[3];   // f0..f2
88	  float dir[3];      // f3..f5
89	  float tmin;        // f6
90	  float tmax;        // f7
91	} vx_ray_t;
92	
93	// The f0..f7 ray window is read by the trace2 decoder by HW convention (the
94	// decoders hardcode f0..f7 with no runtime check) and is fed by the
95	// register-pinned asm operands in vx_rt_wtrace below. Enforce that vx_ray_t is
96	// exactly the eight contiguous floats those operands map onto, so a field
97	// reorder or added padding fails to compile rather than silently scrambling
98	// the per-lane ray window streamed into the RTU.
99	_Static_assert(sizeof(vx_ray_t) == 8 * sizeof(float),
100	               "vx_ray_t must be exactly the 8-float f0..f7 ray window (no padding)");
101	_Static_assert(offsetof(vx_ray_t, origin) == 0,                 "vx_ray_t.origin -> f0..f2");
102	_Static_assert(offsetof(vx_ray_t, dir)    == 3 * sizeof(float), "vx_ray_t.dir -> f3..f5");
103	_Static_assert(offsetof(vx_ray_t, tmin)   == 6 * sizeof(float), "vx_ray_t.tmin -> f6");
104	_Static_assert(offsetof(vx_ray_t, tmax)   == 7 * sizeof(float), "vx_ray_t.tmax -> f7");
105	
106	// Hit attributes written back by vx_rt_wait: floats to the FP file, IDs to the
107	// GP file (the type-split keeps floats and IDs in their natural files — no fmv
108	// conversions).
109	typedef struct {
110	  float    t;
111	  float    u;
112	  float    v;
113	  uint32_t primitive_id;
114	  uint32_t geometry_index;
115	  uint32_t instance_id;
116	  uint32_t instance_custom;   // gl_InstanceCustomIndexEXT (VK_INSTANCE_CUSTOM_INDEX)
117	} vx_hit_t;
118	
119	// The struct field order (memory layout) is intentionally NOT the RTU register-
120	// window slot order: the ID window reads slots 21..24 =
121	// {primitive_id, instance_id, geometry_index, instance_custom}, whereas this
122	// struct groups geometry_index BEFORE instance_id. vx_rt_wait() marshals each
123	// slot into its named field individually, so the two orders are decoupled — do
124	// NOT bulk-copy the register window into this struct. The asserts pin the layout
125	// so a field reorder is caught at compile time.
126	_Static_assert(offsetof(vx_hit_t, t)               == 0 * sizeof(float), "vx_hit_t.t");
127	_Static_assert(offsetof(vx_hit_t, u)               == 1 * sizeof(float), "vx_hit_t.u");
128	_Static_assert(offsetof(vx_hit_t, v)               == 2 * sizeof(float), "vx_hit_t.v");
129	_Static_assert(offsetof(vx_hit_t, primitive_id)    == 3 * sizeof(float), "vx_hit_t.primitive_id");
130	_Static_assert(offsetof(vx_hit_t, geometry_index)  == 4 * sizeof(float), "vx_hit_t.geometry_index");
131	_Static_assert(offsetof(vx_hit_t, instance_id)     == 5 * sizeof(float), "vx_hit_t.instance_id");
132	_Static_assert(offsetof(vx_hit_t, instance_custom) == 6 * sizeof(float), "vx_hit_t.instance_custom");
133	
134	// vx_rt_wtrace — issue one ray in a single warp-level (macro) instruction. The
135	// 'w' marks it warp-scoped: rs1 is the lane-packed warp-uniform config read
136	// across the warp's lanes, and the f0..f7 ray window is per-lane.
137	//   scene_ptr / payload_ptr / ray_flags / cull_mask : per-trace warp-uniform
138	//     config, lane-packed into one register via an IMPLICIT vx_wgather
139	//     (lane0=scene, lane1=payload, lane2=flags, lane3=cull) — pure register
140	//     domain, no memory traffic; hoists out of a bounce loop when invariant.
141	//   ray : the per-thread geometry, pinned into the f0..f7 caller-saved window.
142	// Returns the async ray handle in rd. Non-blocking: the RTU traverses
143	// while the kernel runs independent work; vx_rt_wait is the sync point.
144	static inline __attribute__((always_inline))
145	uint32_t vx_rt_wtrace(uint32_t scene_ptr, uint32_t payload_ptr,
146	                     uint32_t ray_flags, uint32_t cull_mask,
147	                     const vx_ray_t* ray) {
148	  // Pack config into the GATHERED operands (not the wgather self slot): the
149	  // self slot is write-suppressed and so is the one word the partial-warp
150	  // wgather can't materialise from a live lane. lane1=scene, lane2=payload,
151	  // lane3={flags,cull}; lane0 (self) unused. Keeps scene valid even when lane 0
152	  // is masked (callback/recursion-narrowed traces).
153	  uint32_t flags_cull = (ray_flags & 0xffffu) | (cull_mask << 16);
154	  uint32_t cfg = (uint32_t)vx_wgather(0u, scene_ptr, payload_ptr, flags_cull);
155	  register float r0 __asm__("f0") = ray->origin[0];
156	  register float r1 __asm__("f1") = ray->origin[1];
157	  register float r2 __asm__("f2") = ray->origin[2];
158	  register float r3 __asm__("f3") = ray->dir[0];
159	  register float r4 __asm__("f4") = ray->dir[1];
160	  register float r5 __asm__("f5") = ray->dir[2];
161	  register float r6 __asm__("f6") = ray->tmin;
162	  register float r7 __asm__("f7") = ray->tmax;
163	  uint32_t handle;
164	  // rd = handle, rs1 = cfg, rs2 = x0. The f0..f7 window rides the operand
165	  // list (read by HW convention, like the tensor unit's fragment window);
166	  // the encoding itself only names rd/rs1. Named operands (not %0/%1) keep
167	  // the field references stable across the long register-binding list.
168	  __asm__ volatile (".insn r %[op], 7, 0, %[hnd], %[cfg], x0"
169	    : [hnd]"=r"(handle)
170	    : [op]"i"(RISCV_CUSTOM1), [cfg]"r"(cfg),
171	      "f"(r0), "f"(r1), "f"(r2), "f"(r3),
172	      "f"(r4), "f"(r5), "f"(r6), "f"(r7));
173	  return handle;
174	}
175	
176	// vx_rt_wait — block on the ray handle until terminal, return the status word,
177	// and write the hit attributes back to their natural register files. Emitted as
178	// TWO ops so it composes with callback-yielding traces:
179	//   (1) WAIT2 (funct2=1) — a SINGLE-OP block. It parks/revives exactly like the
180	//       register-file get path, so it survives the async callback trap (a parked
181	//       single op is revived by HW on terminal; a parking macro-op could not
182	//       have its writeback uops resumed after the trap flush).
183	//   (2) WAIT_WB (funct2=3) — a NON-blocking hit-window writeback macro-op,
184	//       scoreboard-chained on the status word, so it issues only after the
185	//       block retired (terminal). Running post-terminal, it never coincides
186	//       with a callback trap. Hit window: t/u/v -> f0..f2, IDs -> t3..t5.
187	// The "memory" clobber on the block keeps a callback-written memory load placed
188	// after the wait from hoisting above it.
189	static inline __attribute__((always_inline))
190	uint32_t vx_rt_wait(uint32_t handle, vx_hit_t* hit) {
191	  uint32_t status;
192	  __asm__ volatile (".insn r %[op], 7, 1, %[sts], %[hnd], x0"
193	    : [sts]"=r"(status)
194	    : [op]"i"(RISCV_CUSTOM1), [hnd]"r"(handle)
195	    : "memory");
196	  // (2a) hit t/u/v via an FP windowed read (slots HIT_T..HIT_BARY_V -> f0..f2),
197	  // chained on status (rs1) so it issues only after the block's terminal staged
198	  // the hit. Single register class -> reliable codegen.
199	  register float ht __asm__("f0");
200	  register float hu __asm__("f1");
201	  register float hv __asm__("f2");
202	  __asm__ volatile (".insn r %[op], 6, %[f7], %[w0], %[sts], x3"
203	    : [w0]"=f"(ht), "=f"(hu), "=f"(hv)
204	    : [op]"i"(RISCV_CUSTOM1), [f7]"i"(((VX_RT_HIT_T) << 2) | 2), [sts]"r"(status));
205	  // (2b) hit IDs via a GP windowed read (slots HIT_PRIMITIVE_ID..,+3 -> t3..t6):
206	  // 21 = primitive_id, 22 = instance_id, 23 = geometry_index,
207	  // 24 = instance_custom (gl_InstanceCustomIndexEXT).
208	  register uint32_t hp __asm__("t3");
209	  register uint32_t hi __asm__("t4");
210	  register uint32_t hg __asm__("t5");
211	  register uint32_t hc __asm__("t6");
212	  __asm__ volatile (".insn r %[op], 6, %[f7], %[w0], %[sts], x4"
213	    : [w0]"=r"(hp), "=r"(hi), "=r"(hg), "=r"(hc)
214	    : [op]"i"(RISCV_CUSTOM1), [f7]"i"(((VX_RT_HIT_PRIMITIVE_ID) << 2) | 3), [sts]"r"(status));
215	  hit->t = ht;
216	  hit->u = hu;
217	  hit->v = hv;
218	  hit->primitive_id    = hp;
219	  hit->instance_id     = hi;
220	  hit->geometry_index  = hg;
221	  hit->instance_custom = hc;
222	  return status;
223	}
224	
225	// ===========================================================================
226	// Callback-side register-window read. The v2 trace/wait path
227	// collapsed the kernel's field-by-field marshalling; this does the same for the
228	// in-trap callback read path: a dispatcher that needs several
229	// contiguous float slots (e.g. the object-space ray an IS shader reads) issues
230	// ONE windowed read instead of N vx_gfx_get + N fmv. Encoding: CUSTOM1 /
231	// funct3 = 6 / funct2 = 2 (GETWF); the window start slot rides funct7[6:2] and
232	// the slot count rides the rs2 register-field index (an immediate). Values land
233	// in an FP register group with no int->float conversion.
234	// ===========================================================================
235	
236	// Object-space ray staged by the RTU on an AHS/IS yield (slots
237	// VX_RT_OBJECT_RAY_ORIGIN..DIRECTION, six contiguous floats).
238	typedef struct {
239	  float origin[3];
240	  float dir[3];
241	} vx_objray_t;
242	
243	// vx_rt_get_objray — read the six object-ray floats (VX_RT_OBJECT_RAY_ORIGIN..
244	// DIRECTION) into the f0..f5 window in one macro-op. Replaces the 6x vx_gfx_get
245	// + 6x fmv an intersection-shader dispatcher would otherwise emit. Call inside
246	// a callback dispatcher (the regfile holds the candidate's object-space ray
247	// after the yield).
248	static inline __attribute__((always_inline))
249	void vx_rt_get_objray(vx_objray_t* out) {
250	  register float r0 __asm__("f0");
251	  register float r1 __asm__("f1");
252	  register float r2 __asm__("f2");
253	  register float r3 __asm__("f3");
254	  register float r4 __asm__("f4");
255	  register float r5 __asm__("f5");
256	  // rd = f0 (window base), rs2 = x6 (count = 6); funct7 = (start_slot << 2) | 2.
257	  __asm__ volatile (".insn r %[op], 6, %[f7], %[w0], x0, x6"
258	    : [w0]"=f"(r0), "=f"(r1), "=f"(r2), "=f"(r3), "=f"(r4), "=f"(r5)
259	    : [op]"i"(RISCV_CUSTOM1),
260	      [f7]"i"(((VX_RT_OBJECT_RAY_ORIGIN) << 2) | 2));
261	  out->origin[0] = r0; out->origin[1] = r1; out->origin[2] = r2;
262	  out->dir[0]    = r3; out->dir[1]    = r4; out->dir[2]    = r5;
263	}
264	
265	// vx_rt_wtrace_sync — fused trace+wait for the common ray-query case where the
266	// kernel needs the hit immediately (no independent work to overlap). This does
267	// NOT earn a dedicated opcode: a real fused instruction would have to PARK
268	// mid-macro-op (between arm and writeback),
269	// adding sequencer/scoreboard complexity, and it would forfeit the async
270	// overlap that is the whole point of the trace/wait split — all to save a
271	// single instruction fetch (the handle never leaves a register anyway). So the
272	// sync form is just the two v2 macro-ops back to back; when the kernel DOES
273	// have independent work, it calls trace/wait separately and the compiler
274	// schedules that work into the gap.
275	static inline __attribute__((always_inline))
276	uint32_t vx_rt_wtrace_sync(uint32_t scene_ptr, uint32_t payload_ptr,
277	                          uint32_t ray_flags, uint32_t cull_mask,
278	                          const vx_ray_t* ray, vx_hit_t* hit) {
279	  uint32_t h = vx_rt_wtrace(scene_ptr, payload_ptr, ray_flags, cull_mask, ray);
280	  return vx_rt_wait(h, hit);
281	}
282	
283	#ifdef __cplusplus
284	}
285	#endif
