36	
37	RtuUnit::RtuUnit(Core* core, SimChannel<RtuReq>& req_out, GfxWindow& window)
38	  : window_(window)
39	  , core_(core)
40	  , req_out_(req_out)
41	{
42	  trace2_slot_.fill(-1);
43	  for (auto& s : trace2_scene_) s.fill(0);
44	}
45	
46	uint32_t RtuUnit::wait_handle(const instr_trace_t* trace) {
47	  // handle = TRACE's rd = WAIT's rs1. Assumes all active lanes carry
48	  // the same handle (one TRACE allocates one slot covering the whole
49	  // warp). Read the first active lane's rs1 as the canonical handle
50	  // for the WAIT.
51	  for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
52	    if (trace->tmask.test(t)) {
53	      return static_cast<uint32_t>(trace->src_data[0].at(t).u);
54	    }
55	  }
56	  return 0;
57	}
58	
59	bool RtuUnit::wait_would_short_circuit(uint32_t wid, uint32_t slot) const {
60	  return pending_terminals_.at(wid).count(slot) != 0;
61	}
62	
63	bool RtuUnit::terminal_would_writeback(const RtuRsp& rsp,
64	                                       uint32_t* out_block_id) const {
65	  const auto& parked = wait_parked_.at(rsp.warp_id);
66	  auto it = parked.find(rsp.slot_idx);
67	  if (it == parked.end()) return false;
68	  if (out_block_id) *out_block_id = it->second.block_id;
69	  return true;
70	}
71	
72	instr_trace_t* RtuUnit::process_wait(instr_trace_t* trace, uint32_t block_id) {
73	  uint32_t slot = wait_handle(trace);
74	  auto& pending = pending_terminals_.at(trace->wid);
75	  auto it = pending.find(slot);
76	  if (it == pending.end()) {
77	    // TERMINAL hasn't landed yet — park the trace and bail. The
78	    // matching on_terminal_rsp() call will revive it. dst_data
79	    // stays uninitialised; SfuUnit won't output.send the parked
80	    // trace, so scoreboard keeps WAIT's rd reserved (which is
81	    // exactly the ordering that gates vx_rt_get_after).
82	    trace->suspended = true;  // holds its rd reserved while parked; an async
83	                              // callback trap lifts only suspended reservations
84	    wait_parked_.at(trace->wid)[slot] = ParkedWait{trace, block_id};
85	    DT(3, "rtu-wait park: core=" << core_->id() << ", wid=" << trace->wid
86	         << ", slot=" << slot);
87	    return nullptr;
88	  }
89	  // Fast path: TERMINAL was already cached. Apply it to the regfile
90	  // now (so vx_rt_get_after that follows reads coherent hit data)
91	  // and write the per-lane status word into trace's dst_data so
92	  // the SFU output.send delivers it.
93	  const RtuRsp& rsp = it->second;
94	  apply_response(rsp);
95	  for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
96	    trace->dst_data[t].u = trace->tmask.test(t) ? rsp.status[t] : 0;
97	  }
98	  pending.erase(it);
99	  rtu_core_->free_slot(slot);
100	  DT(3, "rtu-wait short-circuit: core=" << core_->id() << ", wid=" << trace->wid
101	       << ", slot=" << slot);
102	  return trace;
103	}
104	
105	RtuUnit::PendingWriteback RtuUnit::on_terminal_rsp(const RtuRsp& rsp) {
106	  uint32_t wid  = rsp.warp_id;
107	  uint32_t slot = rsp.slot_idx;
108	  auto& parked = wait_parked_.at(wid);
109	  auto it = parked.find(slot);
110	  if (it == parked.end()) {
111	    // WAIT hasn't issued yet — latch the rsp. Slot stays live in
112	    // RtuCore (EMITTED state) until the eventual WAIT consumes the
113	    // pending_terminals_ entry and calls free_slot.
114	    pending_terminals_.at(wid)[slot] = rsp;
115	    DT(3, "rtu-terminal latch: core=" << core_->id() << ", wid=" << wid
116	         << ", slot=" << slot);
117	    return {nullptr, 0};
118	  }
119	  // Common path: WAIT was parked, now we can complete it. Apply
120	  // hit attrs to the regfile so post-WAIT vx_rt_get_after sees
121	  // coherent data; write status word into the parked trace's
122	  // dst_data; return it so SfuUnit can output.send.
123	  ParkedWait pw = it->second;
124	  parked.erase(it);
125	  pw.trace->suspended = false;  // flowing again — releases its rd on commit
126	  apply_response(rsp);
127	  for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
128	    pw.trace->dst_data[t].u = pw.trace->tmask.test(t) ? rsp.status[t] : 0;
129	  }
130	  rtu_core_->free_slot(slot);
131	  DT(3, "rtu-terminal deliver: core=" << core_->id() << ", wid=" << wid
132	       << ", slot=" << slot << ", block=" << pw.block_id);
133	  return {pw.trace, pw.block_id};
134	}
135	
136	instr_trace_t* RtuUnit::process_cb_ret(instr_trace_t* trace, uint32_t block_id) {
137	  // vx_rt_cb_ret releases per-lane parked contexts. Per lane it
138	  // reports an action code (ACCEPT/IGNORE/TERMINATE) AND the slot
139	  // handle (from VX_RT_CB_HANDLE, staged by apply_callback_payload
140	  // at CB_YIELD time). The RtuCore CB_ACTION drain uses the per-lane
141	  // handle to route the action back to the originating slot —
142	  // necessary because same-warp reformation may bundle lanes from
143	  // multiple slots into one CB_YIELD trap.
144	  if (req_out_.full()) {
145	    return nullptr;
146	  }
147	  auto& wregs = window_.warp(trace->wid);
148	  RtuReq req;
149	  req.kind     = RtuReqKind::CB_ACTION;
150	  req.uuid     = trace->uuid;
151	  req.tag      = uint32_t(trace->uuid);
152	  req.trace    = trace;
153	  req.block_id = block_id;
154	  req.warp_id  = trace->wid;
155	  uint32_t bits = 0;
156	  for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
157	    if (!trace->tmask.test(t)) continue;
158	    bits |= (1u << t);
159	    // rs1 holds the action (ACCEPT/IGNORE/TERMINATE).
160	    req.cb_action[t] = static_cast<uint32_t>(trace->src_data[0].at(t).u);
161	    req.cb_handle[t] = wregs.at(t)[VX_RT_CB_HANDLE];
162	    // The IS dispatcher may have written the real hit distance into
163	    // VX_RT_HIT_T; carry it back so the RtuCore commits the IS t (not the
164	    // pre-IS AABB-entry candidate) on ACCEPT of a procedural primitive.
165	    req.cb_hit_t[t]  = bits_to_float(wregs.at(t)[VX_RT_HIT_T]);
166	    trace->dst_data[t].u = 0;  // no writeback
167	  }
168	  req.tmask_bits = bits;
169	  req_out_.send(req);
170	  DT(3, "rtu-cb_ret submit: core=" << core_->id() << ", wid=" << trace->wid
171	       << ", tmask=0x" << std::hex << bits << std::dec);
172	  return trace;
173	}
174	
175	void RtuUnit::apply_response(const RtuRsp& rsp) {
176	  auto& wregs = window_.warp(rsp.warp_id);
177	  for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
178	    auto& lregs = wregs.at(t);
179	    lregs[VX_RT_HIT_T]              = float_to_bits(rsp.hit_t[t]);
180	    lregs[VX_RT_HIT_BARY_U]         = float_to_bits(rsp.hit_bary_u[t]);
181	    lregs[VX_RT_HIT_BARY_V]         = float_to_bits(rsp.hit_bary_v[t]);
182	    lregs[VX_RT_HIT_PRIMITIVE_ID]   = rsp.hit_primitive_id[t];
183	    lregs[VX_RT_HIT_INSTANCE_ID]    = rsp.hit_instance_id[t];
184	    lregs[VX_RT_HIT_INSTANCE_CUSTOM] = rsp.hit_instance_custom[t];
185	    lregs[VX_RT_HIT_GEOMETRY_INDEX] = rsp.hit_geometry_index[t];
186	    // Committed hit's object-space ray, for a CHS / post-wait read of
187	    // gl_ObjectRay{Origin,Direction}EXT.
188	    lregs[VX_RT_OBJECT_RAY_ORIGIN + 0]    = float_to_bits(rsp.obj_o_x[t]);
189	    lregs[VX_RT_OBJECT_RAY_ORIGIN + 1]    = float_to_bits(rsp.obj_o_y[t]);
190	    lregs[VX_RT_OBJECT_RAY_ORIGIN + 2]    = float_to_bits(rsp.obj_o_z[t]);
191	    lregs[VX_RT_OBJECT_RAY_DIRECTION + 0] = float_to_bits(rsp.obj_d_x[t]);
192	    lregs[VX_RT_OBJECT_RAY_DIRECTION + 1] = float_to_bits(rsp.obj_d_y[t]);
193	    lregs[VX_RT_OBJECT_RAY_DIRECTION + 2] = float_to_bits(rsp.obj_d_z[t]);
194	  }
195	}
196	
197	void RtuUnit::apply_callback_payload(const RtuRsp& rsp) {
198	  // Stage candidate-hit attrs + cb_type + cb_handle into the RTU regs
199	  // for the lanes whose rays yielded, so the dispatcher's vx_rt_get
200	  // sees the right payload AND so vx_rt_cb_ret can route the action
201	  // back to the originating slot. Only the yielded lanes
202	  // (cb_active_mask) are touched. With same-warp reformation we may
203	  // batch lanes from MULTIPLE slots into one CB_YIELD, so
204	  // VX_RT_CB_HANDLE is per-lane (not warp-scoped).
205	  auto& wregs = window_.warp(rsp.warp_id);
206	  for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
207	    if (((rsp.cb_active_mask >> t) & 1u) == 0) continue;
208	    auto& lregs = wregs.at(t);
209	    lregs[VX_RT_HIT_T]              = float_to_bits(rsp.hit_t[t]);
210	    lregs[VX_RT_HIT_BARY_U]         = float_to_bits(rsp.hit_bary_u[t]);
211	    lregs[VX_RT_HIT_BARY_V]         = float_to_bits(rsp.hit_bary_v[t]);
212	    lregs[VX_RT_HIT_PRIMITIVE_ID]   = rsp.hit_primitive_id[t];
213	    lregs[VX_RT_HIT_INSTANCE_ID]    = rsp.hit_instance_id[t];
214	    lregs[VX_RT_HIT_INSTANCE_CUSTOM] = rsp.hit_instance_custom[t];
215	    lregs[VX_RT_HIT_GEOMETRY_INDEX] = rsp.hit_geometry_index[t];
216	    lregs[VX_RT_CB_TYPE]            = rsp.cb_type[t];
217	    lregs[VX_RT_CB_HANDLE]          = rsp.cb_handle[t];
218	    lregs[VX_RT_HIT_SBT_IDX]        = rsp.cb_sbt_idx[t];
219	    // Candidate's object-space ray, so the AHS/IS dispatcher can read
220	    // gl_ObjectRay{Origin,Direction}EXT before computing the
221	    // procedural intersection.
222	    lregs[VX_RT_OBJECT_RAY_ORIGIN + 0]    = float_to_bits(rsp.obj_o_x[t]);
223	    lregs[VX_RT_OBJECT_RAY_ORIGIN + 1]    = float_to_bits(rsp.obj_o_y[t]);
224	    lregs[VX_RT_OBJECT_RAY_ORIGIN + 2]    = float_to_bits(rsp.obj_o_z[t]);
225	    lregs[VX_RT_OBJECT_RAY_DIRECTION + 0] = float_to_bits(rsp.obj_d_x[t]);
226	    lregs[VX_RT_OBJECT_RAY_DIRECTION + 1] = float_to_bits(rsp.obj_d_y[t]);
227	    lregs[VX_RT_OBJECT_RAY_DIRECTION + 2] = float_to_bits(rsp.obj_d_z[t]);
228	  }
229	}
230	
231	///////////////////////////////////////////////////////////////////////////////
232	// Macro-op micro-op generator + the per-uop TRACE2 / WAIT2 handlers.
233	///////////////////////////////////////////////////////////////////////////////
234	
235	namespace {
236	// Low 32 bits of a (NaN-boxed) FP source operand = the raw f32 bits.
237	inline uint32_t fp_src_bits(const instr_trace_t* trace, uint32_t src, uint32_t t) {
238	  return static_cast<uint32_t>(trace->src_data[src].at(t).u64 & 0xffffffffu);
239	}
240	} // namespace
241	
242	uint32_t RtuUopGen::uop_count(const Instr& instr) {
243	  if (instr.get_fu_type() != FUType::SFU)
244	    return 1;
245	  auto op = instr.get_op_type();
246	  if (auto rtu_p = std::get_if<RtuType>(&op)) {
247	    if (*rtu_p == RtuType::TRACE2)  return 4;  // 1 GP config + 3 FP ray
248	    if (*rtu_p == RtuType::GETWF || *rtu_p == RtuType::GETW) {
249	      auto args = std::get<IntrRtuArgs>(instr.get_args());  // one uop per slot
250	      return args.count ? args.count : 1;
251	    }
252	  }
253	  return 1;
254	}
255	
256	Instr::Ptr RtuUopGen::get(const Instr& macro_instr, uint32_t uop_index) {
257	  auto rtu_type = std::get<RtuType>(macro_instr.get_op_type());
258	  uint64_t parent_uuid = macro_instr.get_uuid();
259	  uint32_t total = uop_count(macro_instr);
260	
261	  uint32_t uuid_hi = (parent_uuid >> 32) & 0xffffffff;
262	  uint32_t uuid_lo = parent_uuid & 0xffffffff;
263	  uint32_t steps_shift = (total > 1) ? (32 - log2ceil(total)) : 0;
264	  uint64_t uop_uuid = (uint64_t(uuid_hi) << 32) | ((uop_index << steps_shift) | uuid_lo);
265	
266	  auto uop = std::allocate_shared<Instr>(pool_, uop_uuid, FUType::SFU);
267	  uop->set_parent_uuid(parent_uuid);
268	  uop->set_op_type(rtu_type);
269	
270	  auto macro_args = std::get<IntrRtuArgs>(macro_instr.get_args());
271	  IntrRtuArgs args{};
272	  args.uop = uop_index;
273	  args.slot = macro_args.slot;
274	  args.count = macro_args.count;
275	  uop->set_args(args);
276	
277	  uint32_t rd_idx  = macro_instr.get_dest_reg().idx;   // handle / status / window base
278	  uint32_t rs1_idx = macro_instr.get_src_reg(0).idx;   // config / handle
279	
280	  if (rtu_type == RtuType::GETWF || rtu_type == RtuType::GETW) {
281	    // Windowed read: uop i writes window slot (start+i) into reg (rd_base + i).
282	    // No source operands — the data comes from the RTU regfile. GETWF -> FP
283	    // (NaN-boxed), GETW -> GP (raw).
284	    uop->set_dest_reg(rd_idx + uop_index,
285	                      rtu_type == RtuType::GETWF ? RegType::Float : RegType::Integer);
286	  } else if (rtu_type == RtuType::TRACE2) {
287	    // f0..f7 ray window streamed three regs per uop.
288	    switch (uop_index) {
289	    case 0: // GP config: read rs1 lanes, alloc slot, write handle.
290	      uop->set_dest_reg(rd_idx, RegType::Integer);
291	      uop->set_src_reg(0, rs1_idx, RegType::Integer);
292	      break;
293	    case 1: // origin.xyz <- f0,f1,f2
294	      uop->set_src_reg(0, 0, RegType::Float);
295	      uop->set_src_reg(1, 1, RegType::Float);
296	      uop->set_src_reg(2, 2, RegType::Float);
297	      break;
298	    case 2: // dir.xyz <- f3,f4,f5
299	      uop->set_src_reg(0, 3, RegType::Float);
300	      uop->set_src_reg(1, 4, RegType::Float);
301	      uop->set_src_reg(2, 5, RegType::Float);
302	      break;
303	    case 3: // tmin,tmax <- f6,f7 (then arm)
304	      uop->set_src_reg(0, 6, RegType::Float);
305	      uop->set_src_reg(1, 7, RegType::Float);
306	      break;
307	    default:
308	      std::abort();
309	    }
310	  } else {
311	    std::abort();  // only TRACE2 / GETWF / GETW are SFU macro-ops
312	  }
313	  // Windowed reads carry an optional scoreboard-chain source on rs1 (x0 = none):
314	  // vx_rt_wait2 sets it to the WAIT2 status so the window issues only after the
315	  // block retired and apply_response staged the hit. In-trap callback reads
316	  // (vx_rt_get_objray) leave it x0 — the dispatcher already runs post-yield.
317	  if (rtu_type == RtuType::GETWF || rtu_type == RtuType::GETW) {
318	    uop->set_src_reg(0, rs1_idx, RegType::Integer);
319	  }
320	  return uop;
321	}
322	
323	bool RtuUnit::trace2_reserve_slot(uint32_t wid) {
324	  if (rtu_core_ == nullptr) {
325	    return false;
326	  }
327	  if (trace2_slot_.at(wid) >= 0) {
328	    return true; // this warp's TRACE2 already holds a slot
329	  }
330	  int32_t slot = rtu_core_->allocate_slot();
331	  if (slot < 0) {
332	    return false;
333	  }
334	  trace2_slot_.at(wid) = slot;
335	  return true;
336	}
337	
338	instr_trace_t* RtuUnit::process_trace2_uop(instr_trace_t* trace, uint32_t block_id, uint32_t uop) {
339	  uint32_t wid = trace->wid;
340	  auto& wregs = window_.warp(wid);
341	  switch (uop) {
342	  case 0: {
343	    // GP config uop: the slot is reserved at issue, so this uop has no
344	    // backpressure source. Unpack the lane-packed config (lane0=scene,
345	    // lane1=payload, lane2=flags, lane3=cull — the implicit vx_wgather layout)
346	    // and stage it.
347	    int32_t slot = trace2_slot_.at(wid);
348	    assert(slot >= 0 && "TRACE2 uop0 issued without a reserved pool slot");
349	    // Config rides the gathered wgather lanes (1..3), never the write-suppressed
350	    // self slot (lane 0), so every word survives a partial/lane-0-dead mask.
351	    // scene = wgather lane 1 (warp-uniform).
352	    auto& cfg = trace->src_data[0];
353	    uint32_t payload   = static_cast<uint32_t>(cfg.at(2).u);
354	    uint32_t flagscull = static_cast<uint32_t>(cfg.at(3).u);
355	    uint32_t flags     = flagscull & 0xffffu;
356	    uint32_t cull      = flagscull >> 16;
357	    for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
358	      if (!trace->tmask.test(t)) continue;
359	      trace2_scene_.at(wid)[t]    = static_cast<uint32_t>(cfg.at(1).u);
360	      auto& lregs = wregs.at(t);
361	      lregs[VX_RT_PAYLOAD_PTR_LO] = payload;
362	      lregs[VX_RT_RAY_FLAGS]      = flags;
363	      lregs[VX_RT_CULL_MASK]      = cull;
364	      trace->dst_data[t].u        = uint32_t(slot);  // handle returns early
365	    }
366	    return trace;
367	  }
368	  case 1:  // origin.xyz <- f0,f1,f2
369	    for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
370	      if (!trace->tmask.test(t)) continue;
371	      auto& lregs = wregs.at(t);
372	      lregs[VX_RT_RAY_ORIGIN + 0] = fp_src_bits(trace, 0, t);
373	      lregs[VX_RT_RAY_ORIGIN + 1] = fp_src_bits(trace, 1, t);
374	      lregs[VX_RT_RAY_ORIGIN + 2] = fp_src_bits(trace, 2, t);
375	    }
376	    return trace;
377	  case 2:  // dir.xyz <- f3,f4,f5
378	    for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
379	      if (!trace->tmask.test(t)) continue;
380	      auto& lregs = wregs.at(t);
381	      lregs[VX_RT_RAY_DIRECTION + 0] = fp_src_bits(trace, 0, t);
382	      lregs[VX_RT_RAY_DIRECTION + 1] = fp_src_bits(trace, 1, t);
383	      lregs[VX_RT_RAY_DIRECTION + 2] = fp_src_bits(trace, 2, t);
384	    }
385	    return trace;
386	  case 3: {  // tmin,tmax <- f6,f7, then ARM the slot.
387	    for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
388	      if (!trace->tmask.test(t)) continue;
389	      auto& lregs = wregs.at(t);
390	      lregs[VX_RT_T_MIN] = fp_src_bits(trace, 0, t);
391	      lregs[VX_RT_T_MAX] = fp_src_bits(trace, 1, t);
392	    }
393	    // ARM: build + send the RtuReq (bus full => retry uop 3 idempotently;
394	    // the slot was already latched at uop 0). Mirrors Phase-1 process_trace's
395	    // body, but reads the scene from the staged config rather than rs1.
396	    if (req_out_.full())
397	      return nullptr;
398	    int32_t slot = trace2_slot_.at(wid);
399	    RtuReq req;
400	    req.kind     = RtuReqKind::TRACE_NEW;
401	    req.uuid     = trace->uuid;
402	    req.tag      = uint32_t(trace->uuid);
403	    req.slot_idx = uint32_t(slot);
404	    req.trace    = trace;
405	    req.block_id = block_id;
406	    req.warp_id  = wid;
407	    uint32_t bits = 0;
408	    for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
409	      if (!trace->tmask.test(t)) continue;
410	      bits |= (1u << t);
411	      auto& lregs = wregs.at(t);
412	      req.scene_root[t] = trace2_scene_.at(wid)[t];
413	      req.origin_x[t]   = bits_to_float(lregs[VX_RT_RAY_ORIGIN + 0]);
414	      req.origin_y[t]   = bits_to_float(lregs[VX_RT_RAY_ORIGIN + 1]);
415	      req.origin_z[t]   = bits_to_float(lregs[VX_RT_RAY_ORIGIN + 2]);
416	      req.dir_x[t]      = bits_to_float(lregs[VX_RT_RAY_DIRECTION + 0]);
417	      req.dir_y[t]      = bits_to_float(lregs[VX_RT_RAY_DIRECTION + 1]);
418	      req.dir_z[t]      = bits_to_float(lregs[VX_RT_RAY_DIRECTION + 2]);
419	      req.tmin[t]       = bits_to_float(lregs[VX_RT_T_MIN]);
420	      req.tmax[t]       = bits_to_float(lregs[VX_RT_T_MAX]);
421	      req.flags[t]      = lregs[VX_RT_RAY_FLAGS];
422	      req.cull_mask[t]  = lregs[VX_RT_CULL_MASK];
423	    }
424	    req.tmask_bits = bits;
425	    req_out_.send(req);
426	    trace2_slot_.at(wid) = -1;
427	    DT(3, "rtu-trace2 arm: core=" << core_->id() << ", wid=" << wid
428	         << ", slot=" << slot << ", tmask=0x" << std::hex << bits << std::dec);
429	    return trace;
430	  }
431	  default:
432	    std::abort();
433	  }
434	}
435	
