58	    float t0 = (mn[i] - ro[i]) * inv;
59	    float t1 = (mx[i] - ro[i]) * inv;
60	    if (t0 > t1) { float tmp = t0; t0 = t1; t1 = tmp; }
61	    if (t0 > tn) tn = t0;
