72	  const float r00 = xform[0],  r01 = xform[1],  r02 = xform[2],  tx = xform[3];
73	  const float r10 = xform[4],  r11 = xform[5],  r12 = xform[6],  ty = xform[7];
74	  const float r20 = xform[8],  r21 = xform[9],  r22 = xform[10], tz = xform[11];
75	
76	  // det(R) by cofactor expansion along row 0.
77	  float det = r00 * (r11 * r22 - r12 * r21)
78	            - r01 * (r10 * r22 - r12 * r20)
79	            + r02 * (r10 * r21 - r11 * r20);
80	  if (det > -1e-9f && det < 1e-9f) {
81	    // Singular — pass through (treat as identity).
82	    for (int i = 0; i < 3; ++i) { ro_out[i] = ro[i]; rd_out[i] = rd[i]; }
83	    return;
84	  }
85	  float inv_det = 1.f / det;
