87	  // R^(-1) = (1/det) * adj(R).
88	  float i00 =  (r11 * r22 - r12 * r21) * inv_det;
89	  float i01 = -(r01 * r22 - r02 * r21) * inv_det;
90	  float i02 =  (r01 * r12 - r02 * r11) * inv_det;
91	  float i10 = -(r10 * r22 - r12 * r20) * inv_det;
92	  float i11 =  (r00 * r22 - r02 * r20) * inv_det;
93	  float i12 = -(r00 * r12 - r02 * r10) * inv_det;
94	  float i20 =  (r10 * r21 - r11 * r20) * inv_det;
95	  float i21 = -(r00 * r21 - r01 * r20) * inv_det;
96	  float i22 =  (r00 * r11 - r01 * r10) * inv_det;
97	
98	  // ro_obj = R^(-1) * (ro - t).
99	  float dx = ro[0] - tx, dy = ro[1] - ty, dz = ro[2] - tz;
100	  ro_out[0] = i00 * dx + i01 * dy + i02 * dz;
101	  ro_out[1] = i10 * dx + i11 * dy + i12 * dz;
102	  ro_out[2] = i20 * dx + i21 * dy + i22 * dz;
103	
104	  // rd_obj = R^(-1) * rd.
105	  rd_out[0] = i00 * rd[0] + i01 * rd[1] + i02 * rd[2];
106	  rd_out[1] = i10 * rd[0] + i11 * rd[1] + i12 * rd[2];
107	  rd_out[2] = i20 * rd[0] + i21 * rd[1] + i22 * rd[2];
