30	namespace vortex { namespace rtu {
31	
32	namespace {
33	
34	// ────────────────────────────────────────────────────────────────────
35	// Walker-local helpers.
36	// ────────────────────────────────────────────────────────────────────
37	
38	// Read `len` bytes from the lane's logical scene buffer at offset
39	// `off` (relative to line 0 + l.line_byte_off), crossing line
40	// boundaries as needed. Out-of-range reads silently return zeros.
41	void read_scene_bytes(const LaneState& l, uint32_t off,
42	                      uint32_t len, uint8_t* out) {
43	  uint32_t base = l.line_byte_off + off;
44	  for (uint32_t i = 0; i < len; ++i) {
45	    uint32_t pos = base + i;
46	    uint32_t li  = pos / VX_CFG_MEM_BLOCK_SIZE;
47	    uint32_t bo  = pos % VX_CFG_MEM_BLOCK_SIZE;
48	    out[i] = (li < kRtuMaxLinesPerLane) ? l.line_data[li][bo] : uint8_t(0);
49	  }
50	}
51	
52	// CW-BVH4: reconstruct a child AABB from quantized representation.
53	//   real = origin + qaabb * 2^exp (per axis)
54	inline void reconstruct_child_aabb(const float origin[3], const int8_t exp[3],
55	                                   const uint8_t qmin[3], const uint8_t qmax[3],
56	                                   float out_mn[3], float out_mx[3]) {
57	  for (int i = 0; i < 3; ++i) {
58	    float scale = std::ldexp(1.0f, exp[i]);
59	    out_mn[i] = origin[i] + static_cast<float>(qmin[i]) * scale;
60	    out_mx[i] = origin[i] + static_cast<float>(qmax[i]) * scale;
61	  }
62	}
63	
64	// Copy a 3-vector (object-space ray capture helper).
65	inline void vcopy3(float dst[3], const float src[3]) {
66	  dst[0] = src[0]; dst[1] = src[1]; dst[2] = src[2];
67	}
68	
69	// Per-lane BVH4 traversal accumulator. Shared across recursive
70	// sub-tree walks so a BLAS hit can update the same best_t that culls
71	// later TLAS-side AABB tests.
72	struct WalkCtx {
73	  float tmin, tmax;
74	  uint32_t ray_flags;
75	  uint32_t ray_cull_mask;  // Vulkan instanceCullMask gate
76	  bool     terminated;     // TERMINATE_ON_FIRST_HIT fired
77	  float best_t, best_u, best_v;
78	  uint32_t best_prim;
79	  uint32_t best_instance;
80	  uint32_t best_custom;    // VK_INSTANCE_CUSTOM_INDEX of the committed instance
81	  uint32_t best_geom;      // gl_GeometryIndexEXT of the committed leaf
82	  bool any_hit;
83	  bool yield_pending;
84	  float yield_t, yield_u, yield_v;
85	  uint32_t yield_prim;
86	  uint32_t yield_sbt;
87	  uint32_t yield_cb_type;
88	  uint32_t yield_instance;
89	  uint32_t yield_custom;   // VK_INSTANCE_CUSTOM_INDEX of the yield candidate
90	  uint32_t yield_geom;     // gl_GeometryIndexEXT of the yield candidate
91	  // Object-space ray of the committed hit (best_obj_*) and the yield
92	  // candidate (yield_obj_*). Set to {ro,rd} at the leaf that wins;
93	  // equals the world ray at the top level (no instance).
94	  float best_obj_o[3],  best_obj_d[3];
95	  float yield_obj_o[3], yield_obj_d[3];
96	};
97	
98	// Depth-first walker for one BVH4 sub-tree under the supplied
99	// (object-space) ray. Recurses on LeafInst so each instance's BLAS
100	// gets walked with its transformed ray. ctx accumulates hits/yields
101	// across the whole call tree.
102	//
103	// The functional traversal stack is unbounded so the oracle never misses a
104	// hit; the HW short-stack (VX_CFG_RTU_STACK_DEPTH) overflow is counted as a
105	// trail-based RESTART and charged in the cost model.
106	// instance_id is the TLAS-assigned ID the caller wants recorded for
107	// any hit found in this sub-tree.
108	void walk_bvh4_subtree(LaneState& l,
109	                       const float ro[3], const float rd[3],
110	                       uint32_t root_off, uint32_t instance_id,
111	                       uint32_t custom_id, uint32_t inst_flags,
112	                       WalkCtx& ctx, PerfStats& perf) {
113	  auto visit_leaf_tri = [&](uint32_t leaf_off, uint32_t count) {
114	    uint8_t hdr_buf[kVxBvhLeafHeaderBytes];
115	    read_scene_bytes(l, leaf_off, sizeof(hdr_buf), hdr_buf);
116	    const VxBvhLeafHeader* hdr =
117	        reinterpret_cast<const VxBvhLeafHeader*>(hdr_buf);
118	    uint32_t leaf_geom = hdr->geometry_index;
119	    uint32_t leaf_prim_base = hdr->prim_base;  // Vulkan gl_PrimitiveID base
120	    uint32_t tris_off = leaf_off + kVxBvhLeafHeaderBytes;
121	    for (uint32_t i = 0; i < count; ++i) {
122	      if (ctx.terminated) return;
123	      uint8_t tri_buf[kVxBvhTriStride];
124	      read_scene_bytes(l, tris_off + i * kVxBvhTriStride,
125	                       kVxBvhTriStride, tri_buf);
126	      const float* tri = reinterpret_cast<const float*>(tri_buf);
127	      uint32_t tri_flags = 0;
128	      std::memcpy(&tri_flags, tri_buf + kPhase2TriFlagsOff,
129	                  sizeof(uint32_t));
130	
131	      float t_hit = 0.f, u = 0.f, v = 0.f;
132	      bool back_facing = false;
133	      ++perf.bvh_tri_tests;
134	      if (!ray_triangle(ro, rd, &tri[0], &tri[3], &tri[6],
135	                        ctx.tmin, ctx.tmax,
136	                        t_hit, u, v, back_facing)) {
137	        continue;
138	      }
139	
140	      TriClassify cls = classify_tri_hit(ctx.ray_flags, tri_flags,
141	                                          inst_flags, back_facing);
142	      if (cls.action == TriAction::Ignore) continue;
143	
144	      if (cls.action == TriAction::Commit) {
145	        if (t_hit < ctx.best_t) {
146	          ctx.best_t = t_hit; ctx.best_u = u; ctx.best_v = v;
147	          ctx.best_prim = leaf_prim_base + i;
148	          ctx.best_instance = instance_id;
149	          ctx.best_custom = custom_id;
150	          ctx.best_geom = leaf_geom;
151	          ctx.any_hit = true;
152	          vcopy3(ctx.best_obj_o, ro);   // object-space ray of this BLAS
153	          vcopy3(ctx.best_obj_d, rd);
154	          if (ctx.yield_pending && ctx.yield_t >= ctx.best_t) {
155	            ctx.yield_pending = false;
156	            ctx.yield_t = ctx.tmax;
157	          }
158	          if (cls.terminate_on_first_hit) {
159	            ctx.terminated = true;
160	            return;
161	          }
162	        }
163	      } else {  // TriAction::Yield
164	        if (t_hit < ctx.best_t && t_hit < ctx.yield_t) {
165	          ctx.yield_pending = true;
166	          ctx.yield_t = t_hit; ctx.yield_u = u; ctx.yield_v = v;
167	          ctx.yield_prim = leaf_prim_base + i;
168	          ctx.yield_instance = instance_id;
169	          ctx.yield_custom = custom_id;
170	          ctx.yield_geom = leaf_geom;
171	          ctx.yield_sbt = cls.yield_sbt_idx;
172	          ctx.yield_cb_type = cls.yield_cb_type;
173	          vcopy3(ctx.yield_obj_o, ro);  // object-space ray for AHS/IS
174	          vcopy3(ctx.yield_obj_d, rd);
175	        }
176	      }
177	    }
178	  };
179	
180	  // Procedural-AABB leaf. Each record is a custom
181	  // primitive's bounding box; a ray-AABB hit yields an IS callback so the
182	  // kernel's intersection shader computes the real hit. The candidate t is
183	  // the AABB entry parameter (a lower bound); the IS supplies the true t
184	  // via VX_RT_HIT_T, committed on ACCEPT (see rtu_core CB_ACTION drain).
185	  auto visit_leaf_proc = [&](uint32_t leaf_off, uint32_t count) {
186	    uint8_t hdr_buf[kVxBvhLeafHeaderBytes];
187	    read_scene_bytes(l, leaf_off, sizeof(hdr_buf), hdr_buf);
188	    const VxBvhLeafHeader* hdr =
189	        reinterpret_cast<const VxBvhLeafHeader*>(hdr_buf);
190	    uint32_t leaf_sbt =
191	        (hdr->flags >> kVxBvhLeafSbtIdxShift) & kVxBvhLeafSbtIdxMask;
192	    uint32_t aabbs_off = leaf_off + kVxBvhLeafHeaderBytes;
193	    for (uint32_t i = 0; i < count; ++i) {
194	      if (ctx.terminated) return;
195	      uint8_t rec_buf[sizeof(VxBvhProcAabb)];
196	      read_scene_bytes(l, aabbs_off + i * uint32_t(sizeof(VxBvhProcAabb)),
197	                       sizeof(rec_buf), rec_buf);
198	      const VxBvhProcAabb* rec =
199	          reinterpret_cast<const VxBvhProcAabb*>(rec_buf);
200	      float t_near = 0.f;
201	      ++perf.bvh_box_tests;
202	      if (!ray_aabb_intersect(ro, rd, rec->aabb_min, rec->aabb_max,
203	                              ctx.tmin, ctx.best_t, t_near)) {
204	        continue;
205	      }
206	      // Procedural primitives are inherently non-opaque (the IS decides the
207	      // hit), so always stage an IS yield for the closest candidate.
208	      if (t_near < ctx.best_t && t_near < ctx.yield_t) {
209	        ctx.yield_pending = true;
210	        ctx.yield_t = t_near; ctx.yield_u = 0.f; ctx.yield_v = 0.f;
211	        ctx.yield_prim = i;
212	        ctx.yield_instance = instance_id;
213	        ctx.yield_custom = custom_id;
214	        ctx.yield_geom = hdr->geometry_index;
215	        ctx.yield_sbt = leaf_sbt;
216	        ctx.yield_cb_type = VX_RT_CB_TYPE_PROC;
217	        vcopy3(ctx.yield_obj_o, ro);
218	        vcopy3(ctx.yield_obj_d, rd);
219	      }
220	    }
221	  };
222	
223	  auto visit_leaf_inst = [&](uint32_t leaf_off, uint32_t count) {
224	    uint32_t insts_off = leaf_off + kVxBvhLeafHeaderBytes;
225	    for (uint32_t i = 0; i < count; ++i) {
226	      uint8_t inst_buf[kVxBvhInstanceStride];
227	      read_scene_bytes(l, insts_off + i * kVxBvhInstanceStride,
228	                       kVxBvhInstanceStride, inst_buf);
229	      const VxBvhInstance* inst =
230	          reinterpret_cast<const VxBvhInstance*>(inst_buf);
231	      // Vulkan instanceCullMask: skip the instance entirely if
232	      // its mask byte and the ray's cull_mask have no bits in
233	      // common. Both default to 0xff in the no-culling path
234	      // (lavapipe / lvp_nir lowers a missing cullMask to 0xff and
235	      // scene generators set the instance byte the same way), so
236	      // existing tests pass unchanged.
237	      if ((inst->cull_mask & ctx.ray_cull_mask & 0xffu) == 0) continue;
238	      // VkGeometryInstanceFlagBits packed into cull_mask bits 15..8.
239	      uint32_t inst_flags =
240	          (inst->cull_mask >> kRtuInstanceFlagsShift) & kRtuInstanceFlagsMask;
241	      float obj_ro[3], obj_rd[3];
242	      affine_inverse_transform_ray(inst->xform, ro, rd, obj_ro, obj_rd);
243	      ++perf.bvh_instance_descents;
244	      walk_bvh4_subtree(l, obj_ro, obj_rd,
245	                        inst->blas_root_byte_offset,
246	                        inst->instance_id,
247	                        inst->custom_id, inst_flags,
248	                        ctx, perf);
249	    }
250	  };
251	
252	  // SimX is the correctness oracle: keep an UNBOUNDED traversal stack so deep
253	  // sub-trees are never dropped. The HW short-stack is only
254	  // VX_CFG_RTU_STACK_DEPTH deep and trail-restarts to re-find subtrees it had to
255	  // evict — it visits the same leaves, just at extra cost.
256	  std::vector<uint32_t> stack;
257	  stack.reserve(VX_CFG_RTU_STACK_DEPTH);
258	  uint32_t current = root_off;
259	  bool have_current = true;
260	
261	  // Safety backstop: a malformed/cyclic acceleration structure (a child offset
262	  // pointing back at an ancestor) would otherwise descend forever with the
263	  // unbounded stack. The ceiling is far above any well-formed scene's node
264	  // count, so it never truncates a legitimate walk.
265	  constexpr uint64_t kMaxNodeVisits = 1ull << 22;
266	  uint64_t node_visits = 0;
267	
268	  while (have_current) {
269	    if (ctx.terminated) break;
270	    if (++node_visits > kMaxNodeVisits) break;
271	    uint8_t kind_buf[4];
272	    read_scene_bytes(l, current, sizeof(kind_buf), kind_buf);
273	    uint32_t kind_word = 0;
274	    std::memcpy(&kind_word, kind_buf, sizeof(uint32_t));
275	    uint32_t kind  = kind_word & kVxBvhKindMask;
276	    uint32_t count = (kind_word >> kVxBvhCountShift) & kVxBvhCountMask;
277	
278	    if (kind == kVxBvhKindLeafTri) {
279	      ++perf.bvh_leaves_fetched;
280	      if (!(ctx.ray_flags & VX_RT_FLAG_SKIP_TRIANGLES)) {
281	        visit_leaf_tri(current, count);
282	      }
283	    } else if (kind == kVxBvhKindLeafInst) {
284	      ++perf.bvh_leaves_fetched;
285	      visit_leaf_inst(current, count);
286	    } else if (kind == kVxBvhKindLeafProc) {
287	      ++perf.bvh_leaves_fetched;
288	      // SKIP_AABBS: symmetric gate with SKIP_TRIANGLES. Otherwise
289	      // ray-test each procedural AABB and yield IS for the closest hit.
290	      if (!(ctx.ray_flags & VX_RT_FLAG_SKIP_AABBS)) {
291	        visit_leaf_proc(current, count);
292	      }
293	    } else if (kind == kVxBvhKindInternal) {
294	      ++perf.bvh_nodes_fetched;
295	      // Width-generic decode: CW-BVH4 (64 B) or CW-BVH6 (96 B) selected by
296	      // scene_kind. Both decode into VxBvhNodeView so the box-test loop and
297	      // the box-PE cycle model are fan-out independent.
298	      VxBvhNodeView nv;
299	#if VX_CFG_RTU_BVH_WIDTH == 6
300	      uint8_t node_buf[sizeof(VxBvh6InternalNode)];
301	      read_scene_bytes(l, current, sizeof(node_buf), node_buf);
302	      decode_bvh6_node(
303	          reinterpret_cast<const VxBvh6InternalNode*>(node_buf), count, nv);
304	#else
305	      uint8_t node_buf[sizeof(VxBvhInternalNode)];
306	      read_scene_bytes(l, current, sizeof(node_buf), node_buf);
307	      decode_bvh4_node(
308	          reinterpret_cast<const VxBvhInternalNode*>(node_buf), count, nv);
309	#endif
310	
311	      struct ChildHit { uint32_t offset; float t_near; };
312	      ChildHit hits[kVxBvhMaxWidth];
313	      uint32_t hit_count = 0;
314	      for (uint32_t i = 0; i < nv.n_children; ++i) {
315	        uint32_t off_word  = nv.child_offsets[i];
316	        uint32_t child_off = off_word & kVxBvhChildOffsetMask;
317	        if (off_word == kVxBvhChildEmpty) continue;
318	        float mn[3], mx[3];
319	        reconstruct_child_aabb(nv.origin, nv.exp,
320	                                nv.qaabb_min[i], nv.qaabb_max[i],
321	                                mn, mx);
322	        float t_near = 0.f;
323	        ++perf.bvh_box_tests;
324	        if (!ray_aabb_intersect(ro, rd, mn, mx,
325	                                ctx.tmin, ctx.best_t, t_near)) {
326	          continue;
327	        }
328	        hits[hit_count++] = { child_off, t_near };
329	      }
330	      // Insertion-sort children by t_near (nearest-first traversal).
331	      for (uint32_t i = 1; i < hit_count; ++i) {
332	        ChildHit h = hits[i];
333	        uint32_t j = i;
334	        while (j > 0 && hits[j-1].t_near > h.t_near) {
335	          hits[j] = hits[j-1]; --j;
336	        }
337	        hits[j] = h;
338	      }
339	      if (hit_count > 0) {
340	        for (uint32_t i = hit_count; i-- > 1; ) {
341	          // Each push past the HW short-stack depth is one subtree the HW would
342	          // have to re-descend for via restart — count it for the cost model,
343	          // but keep it (unbounded) so the functional walk never misses a hit.
344	          if (stack.size() >= VX_CFG_RTU_STACK_DEPTH)
345	            ++perf.bvh_stack_restarts;
346	          stack.push_back(hits[i].offset);
347	        }
348	        current = hits[0].offset;
349	        have_current = true;
350	        continue;
351	      }
352	    }
353	
354	    if (stack.empty()) {
355	      have_current = false;
356	    } else {
357	      current = stack.back();
358	      stack.pop_back();
359	    }
360	  }
361	}
362	
363	// End-of-lane finalise: translates the accumulated walk state into
364	// LaneState writes. Returns true iff a CB_YIELD should be queued
365	// for this lane (the actual queue push is deferred until the slot
366	// finishes draining PE cycles — see the orchestrator). All
367	// the data needed to reconstruct the QueueEntry lives in LaneState
368	// (cb_pending / cb_type / sbt_idx / cand_t / cand_u / cand_v /
369	// cand_prim), so the orchestrator can scan lanes and push without
370	// the walker carrying intermediate state.
371	bool emit_lane_result(Slot& s, LaneState& l, uint32_t t, uint32_t /*slot_idx*/,
372	                      bool     any_hit,
373	                      float    best_t, float    best_u,
374	                      float    best_v, uint32_t best_prim,
375	                      uint32_t best_instance, uint32_t best_custom,
376	                      uint32_t best_geom,
377	                      bool     yield_pending,
378	                      float    yield_t, float    yield_u,
379	                      float    yield_v, uint32_t yield_prim,
380	                      uint32_t yield_sbt, uint32_t yield_cb_type,
381	                      uint32_t yield_instance, uint32_t yield_custom,
382	                      uint32_t yield_geom,
383	                      const float best_obj_o[3], const float best_obj_d[3],
384	                      const float yield_obj_o[3], const float yield_obj_d[3]) {
385	  l.hit       = any_hit;
386	  l.hit_t     = best_t;
387	  l.hit_u     = best_u;
388	  l.hit_v     = best_v;
389	  l.hit_prim  = best_prim;
390	  l.hit_instance_id = any_hit ? best_instance
391	                              : (yield_pending ? yield_instance : 0u);
392	  l.hit_instance_custom = any_hit ? best_custom
393	                                  : (yield_pending ? yield_custom : 0u);
394	  l.hit_geometry  = best_geom;
395	  l.cand_geometry = yield_geom;
396	  // Stash the committed + candidate object-space rays for the regfile
397	  // writeback in rtu_core/rtu_unit.
398	  vcopy3(l.hit_obj_o,  best_obj_o);
399	  vcopy3(l.hit_obj_d,  best_obj_d);
400	  vcopy3(l.cand_obj_o, yield_obj_o);
401	  vcopy3(l.cand_obj_d, yield_obj_d);
402	
403	  LaneAction action = finalise_lane(s.req.flags[t], any_hit,
404	                                     yield_pending, yield_cb_type);
405	  switch (action) {
406	  case LaneAction::TerminalHit:
407	  case LaneAction::TerminalMiss:
408	    return false;
409	  case LaneAction::YieldAhs:
410	  case LaneAction::YieldIs:
411	    l.cb_pending = true;
412	    l.cb_type    = yield_cb_type;
413	    l.sbt_idx    = yield_sbt;
414	    l.cand_t     = yield_t;
415	    l.cand_u     = yield_u;
416	    l.cand_v     = yield_v;
417	    l.cand_prim  = yield_prim;
418	    l.cand_instance = yield_instance;
419	    l.cand_custom   = yield_custom;
420	    return true;
421	  case LaneAction::YieldChs:
422	    l.cb_pending = true;
423	    l.cb_type    = VX_RT_CB_TYPE_CHS;
424	    l.sbt_idx    = 0;
425	    l.cand_t     = best_t;
426	    l.cand_u     = best_u;
427	    l.cand_v     = best_v;
428	    l.cand_prim  = best_prim;
429	    l.cand_instance = best_instance;
430	    l.cand_custom   = best_custom;
431	    // A CHS candidate IS the committed hit, so gl_GeometryIndexEXT
432	    // reads the committed leaf's geometry (not the stale yield_geom).
433	    l.cand_geometry = best_geom;
434	    return true;
435	  case LaneAction::YieldMiss:
436	    l.cb_pending = true;
437	    l.cb_type    = VX_RT_CB_TYPE_MISS;
438	    l.sbt_idx    = 0;
439	    l.cand_t     = 0.f;
440	    l.cand_u     = 0.f;
441	    l.cand_v     = 0.f;
442	    l.cand_prim  = 0;
443	    l.cand_instance = 0;
444	    l.cand_custom   = 0;
445	    return true;
446	  }
447	  return false;  // unreachable
448	}
449	
450	}  // namespace
451	
452	// ════════════════════════════════════════════════════════════════════
453	// FlatWalker
454	// ════════════════════════════════════════════════════════════════════
455	
456	bool FlatWalker::walk_lane(Slot& s, LaneState& l, uint32_t t,
457	                            uint32_t slot_idx) {
458	  // TLAS scenes walk one or more instances; each instance
459	  // points at a BLAS (a triangle list) and (optionally) applies an
460	  // object→world affine transform.
461	  uint32_t num_instances = 1;
462	#ifdef VX_CFG_RTU_TLAS_ENABLE
463	  if (l.instance_count == 0) {
464	    l.hit = false;
465	    return false;
466	  }
467	  num_instances = l.instance_count;
468	#else
469	  if (l.triangle_count == 0) {
470	    l.hit = false;
471	    return false;
472	  }
473	#endif
474	
475	  float best_t = s.req.tmax[t];
476	  float best_u = 0.f;
477	  float best_v = 0.f;
478	  uint32_t best_prim = 0;
479	  uint32_t best_instance = 0;
480	  uint32_t best_custom = 0;
481	  bool any_hit = false;
482	  bool yield_pending = false;
483	  // Init yield_t to tmax so the first non-opaque candidate always
484	  // wins the "closer than current pending candidate" check
485	  // (single-closest-yield).
486	  float yield_t = s.req.tmax[t];
487	  float yield_u = 0.f, yield_v = 0.f;
488	  uint32_t yield_prim = 0;
489	  uint32_t yield_sbt  = 0;
490	  uint32_t yield_cb_type = VX_RT_CB_TYPE_ANYHIT;
491	  uint32_t yield_instance = 0;
492	  uint32_t yield_custom = 0;
493	  float ro[3] = { s.req.origin_x[t], s.req.origin_y[t], s.req.origin_z[t] };
494	  float rd[3] = { s.req.dir_x[t],    s.req.dir_y[t],    s.req.dir_z[t]   };
495	  // Object-space ray of the committed / candidate hit. Default = world
496	  // ray (TriList); set to the transformed ray below when the hit is
497	  // under a TLAS instance.
498	  float best_obj_o[3]  = { ro[0], ro[1], ro[2] };
499	  float best_obj_d[3]  = { rd[0], rd[1], rd[2] };
500	  float yield_obj_o[3] = { ro[0], ro[1], ro[2] };
501	  float yield_obj_d[3] = { rd[0], rd[1], rd[2] };
502	  uint8_t tri_buf[kPhase2TriStride];
503	
504	  // Scan ALL instances (not stopping at the first with a yield candidate): a
505	  // later instance may hold a NEARER opaque hit (which occludes an alpha-tested
506	  // candidate) or a nearer non-opaque candidate. The inner logic already keeps
507	  // the single closest opaque + closest non-opaque via the best_t / yield_t
508	  // monotone compares, so scanning every instance is order-independent and
509	  // matches the Bvh4Walker whole-tree walk. Exception: a terminate-on-first-hit
510	  // commit halts the entire walk (matching Bvh4Walker's ctx.terminated), so no
511	  // later instance can substitute a different reported hit.
512	  bool terminated = false;
513	  for (uint32_t inst_idx = 0; inst_idx < num_instances && !terminated; ++inst_idx) {
514	    uint32_t blas_tri_off   = kRtuSceneHeaderBytes;
515	    uint32_t blas_tri_count = l.triangle_count;
516	    uint32_t cur_custom     = 0;
517	    uint32_t cur_inst_flags = 0;
518	    float ray_o[3] = { ro[0], ro[1], ro[2] };
519	    float ray_d[3] = { rd[0], rd[1], rd[2] };
520	#ifdef VX_CFG_RTU_TLAS_ENABLE
521	    {
522	      uint32_t inst_off = kRtuSceneHeaderBytes
523	                        + inst_idx * kRtuInstanceStride;
524	      uint8_t inst_buf[kRtuInstanceStride];
525	      read_scene_bytes(l, inst_off, sizeof(inst_buf), inst_buf);
526	      // Vulkan instanceCullMask gate — skip the entire
527	      // instance (transform + BLAS scan) before doing the
528	      // affine ray transform when masks don't overlap. Same
529	      // semantics as the BVH4 LeafInst gate in visit_leaf_inst.
530	      uint32_t inst_cull_mask = 0;
531	      std::memcpy(&inst_cull_mask,
532	                  inst_buf + kRtuInstanceCullMaskOff,
533	                  sizeof(uint32_t));
534	      if ((inst_cull_mask & s.req.cull_mask[t] & 0xffu) == 0) continue;
535	      // VkGeometryInstanceFlagBits packed into cull_mask bits 15..8.
536	      cur_inst_flags =
537	          (inst_cull_mask >> kRtuInstanceFlagsShift) & kRtuInstanceFlagsMask;
538	      const float* xform = reinterpret_cast<const float*>(inst_buf);
539	      uint32_t blas_byte_off = 0;
540	      std::memcpy(&blas_byte_off,
541	                  inst_buf + kRtuInstanceBlasOffOff,
542	                  sizeof(uint32_t));
543	      std::memcpy(&cur_custom,
544	                  inst_buf + kRtuInstanceCustomIdOff,
545	                  sizeof(uint32_t));
546	      // World→object ray transform. For pure rotation +
547	      // translation the t parameter is preserved, so the
548	      // BLAS-reported hit_t is also the world hit_t.
549	      affine_inverse_transform_ray(xform, ro, rd, ray_o, ray_d);
550	      uint8_t blas_hdr[4];
551	      read_scene_bytes(l, blas_byte_off, sizeof(blas_hdr), blas_hdr);
552	      uint32_t bcount = 0;
553	      std::memcpy(&bcount, blas_hdr, sizeof(uint32_t));
554	      if (bcount > kRtuMaxTrisPerScene) bcount = kRtuMaxTrisPerScene;
555	      blas_tri_count = bcount;
556	      blas_tri_off   = blas_byte_off + kRtuSceneHeaderBytes;
557	    }
558	#endif
559	    uint32_t n_tris = std::min(blas_tri_count, kRtuMaxTrisPerScene);
560	
561	    // Walk the *full* triangle list. Track best opaque hit and the
562	    // closest non-opaque candidate separately. If a non-opaque
563	    // candidate ends up closer than the best opaque, yield it;
564	    // otherwise the opaque commits and no AHS fires (alpha-test fast
565	    // path).
566	    //
567	    // SKIP_TRIANGLES bails the whole leaf-tri scan. (Flat-list
568	    // scenes only have tri leaves, so SKIP_AABBS is a no-op here.)
569	    const uint32_t ray_flags = s.req.flags[t];
570	    if (ray_flags & VX_RT_FLAG_SKIP_TRIANGLES) {
571	      // Skip all triangles; remaining hit/yield logic falls through
572	      // with no_hit and no pending candidate.
573	    } else
574	    for (uint32_t i = 0; i < n_tris; ++i) {
575	      uint32_t tri_off = blas_tri_off + i * kPhase2TriStride;
576	      read_scene_bytes(l, tri_off, kPhase2TriStride, tri_buf);
577	      const float* tri = reinterpret_cast<const float*>(tri_buf);
578	      uint32_t tri_flags = 0;
579	      std::memcpy(&tri_flags, tri_buf + kPhase2TriFlagsOff,
580	                  sizeof(uint32_t));
581	
582	      float t_hit = 0.f, u = 0.f, v = 0.f;
583	      bool back_facing = false;
584	      ++perf_.bvh_tri_tests;
585	      // Test against ray.tmax (not best_t) so an opaque hit committed
586	      // earlier in this walk doesn't pre-cull a non-opaque candidate
587	      // that might survive an ACCEPT.
588	      if (!ray_triangle(ray_o, ray_d, &tri[0], &tri[3], &tri[6],
589	                        s.req.tmin[t], s.req.tmax[t],
590	                        t_hit, u, v, back_facing)) {
591	        continue;
592	      }
593	
594	      TriClassify cls = classify_tri_hit(ray_flags, tri_flags,
595	                                          cur_inst_flags, back_facing);
596	      if (cls.action == TriAction::Ignore) continue;
597	
598	      if (cls.action == TriAction::Commit) {
599	        if (t_hit < best_t) {
600	          best_t = t_hit; best_u = u; best_v = v; best_prim = i;
601	          best_instance = inst_idx;
602	          best_custom = cur_custom;
603	          any_hit = true;
604	          vcopy3(best_obj_o, ray_o);   // this instance's object ray
605	          vcopy3(best_obj_d, ray_d);
606	          if (yield_pending && yield_t >= best_t) {
607	            yield_pending = false;
608	            yield_t = s.req.tmax[t];
609	          }
610	          if (cls.terminate_on_first_hit) {
611	            // Halt the whole walk: this hit is committed as the result and no
612	            // later triangle or instance may replace it.
613	            s.req.tmax[t] = best_t;
614	            terminated = true;
615	            break;
616	          }
617	        }
618	      } else {  // TriAction::Yield
619	        if (t_hit < best_t && t_hit < yield_t) {
620	          yield_pending = true;
621	          yield_t = t_hit; yield_u = u; yield_v = v; yield_prim = i;
622	          yield_sbt = cls.yield_sbt_idx;
623	          yield_cb_type = cls.yield_cb_type;
624	          yield_instance = inst_idx;
625	          yield_custom = cur_custom;
626	          vcopy3(yield_obj_o, ray_o);  // object ray for AHS/IS
627	          vcopy3(yield_obj_d, ray_d);
628	        }
629	      }
630	    }
631	  }
632	
633	  // Flat-list scenes carry no per-geometry split; report geometry 0.
634	  return emit_lane_result(s, l, t, slot_idx,
635	                          any_hit, best_t, best_u, best_v, best_prim,
636	                          best_instance, best_custom, 0u,
637	                          yield_pending, yield_t, yield_u, yield_v,
638	                          yield_prim, yield_sbt, yield_cb_type,
639	                          yield_instance, yield_custom, 0u,
640	                          best_obj_o, best_obj_d, yield_obj_o, yield_obj_d);
641	}
642	
643	// ════════════════════════════════════════════════════════════════════
644	// Bvh4Walker
645	// ════════════════════════════════════════════════════════════════════
646	
647	bool Bvh4Walker::walk_lane(Slot& s, LaneState& l, uint32_t t,
648	                            uint32_t slot_idx) {
649	  const float ro[3] = { s.req.origin_x[t], s.req.origin_y[t], s.req.origin_z[t] };
650	  const float rd[3] = { s.req.dir_x[t],    s.req.dir_y[t],    s.req.dir_z[t]   };
651	
652	  WalkCtx ctx;
653	  ctx.tmin = s.req.tmin[t];
654	  ctx.tmax = s.req.tmax[t];
655	  ctx.ray_flags = s.req.flags[t];
656	  ctx.ray_cull_mask = s.req.cull_mask[t];
657	  ctx.terminated = false;
658	  ctx.best_t = ctx.tmax;
659	  ctx.best_u = 0.f; ctx.best_v = 0.f;
660	  ctx.best_prim = 0; ctx.best_instance = 0; ctx.best_custom = 0; ctx.best_geom = 0;
661	  ctx.any_hit = false;
662	  ctx.yield_pending = false;
663	  ctx.yield_t = ctx.tmax; ctx.yield_u = 0.f; ctx.yield_v = 0.f;
664	  ctx.yield_prim = 0; ctx.yield_sbt = 0;
665	  ctx.yield_cb_type = VX_RT_CB_TYPE_ANYHIT;
666	  ctx.yield_instance = 0; ctx.yield_custom = 0; ctx.yield_geom = 0;
667	  // Default object ray = world ray (overwritten at a BLAS leaf if the hit
668	  // is under an instance).
669	  vcopy3(ctx.best_obj_o, ro);  vcopy3(ctx.best_obj_d, rd);
670	  vcopy3(ctx.yield_obj_o, ro); vcopy3(ctx.yield_obj_d, rd);
671	
672	  // Top-level (non-instanced) triangles carry no instance flags.
673	  walk_bvh4_subtree(l, ro, rd, l.bvh_root_offset, 0, 0, 0, ctx, perf_);
674	
675	  return emit_lane_result(s, l, t, slot_idx,
676	                          ctx.any_hit, ctx.best_t, ctx.best_u, ctx.best_v,
677	                          ctx.best_prim, ctx.best_instance, ctx.best_custom,
678	                          ctx.best_geom,
679	                          ctx.yield_pending, ctx.yield_t, ctx.yield_u,
680	                          ctx.yield_v, ctx.yield_prim, ctx.yield_sbt,
681	                          ctx.yield_cb_type, ctx.yield_instance, ctx.yield_custom,
682	                          ctx.yield_geom,
683	                          ctx.best_obj_o, ctx.best_obj_d,
684	                          ctx.yield_obj_o, ctx.yield_obj_d);
685	}
686	
687	}}  // namespace vortex::rtu
