260	//   ISSUE → AWAIT(per-lane cache-line fetches) → COMPUTE → RESP
261	//
262	// Lanes share the same scene_root in the smoke test (single AS per
263	// dispatch), so we issue at most NUM_THREADS distinct cache-line
264	// addresses per request (coalesced when identical).
265	
266	class RtuCore::Impl {
267	public:
268	  // Slot, LaneState, SlotState and QueueEntry live in rtu_types.h
269	  // (vortex::rtu namespace); the file-scope `using namespace
270	  // vortex::rtu;` brings them in unqualified.
271	  using State = SlotState;  // local alias for SlotState
272	
273	  // Sub-modules bind references to perf_stats_ / pool_ / reform_;
274	  // declaration order in the private section below matches this init
275	  // list so -Wreorder stays clean.
276	  explicit Impl(RtuCore* simobject)
277	    : simobject_(simobject)
278	    , pool_(VX_CFG_RTU_NUM_CTX)   // in-flight ray-context pool size
279	    , perf_stats_()
280	    , reform_(simobject->rtu_rsp_out, perf_stats_)
281	#if VX_CFG_RTU_BVH_WIDTH == 0
282	    , flat_walker_(perf_stats_, reform_.queue())
283	#else
284	    , bvh4_walker_(perf_stats_, reform_.queue())
285	#endif
286	    , mem_engine_(pool_.slots(),
287	                   simobject->dcache_req_out,
288	                   simobject->dcache_rsp_in,
289	                   perf_stats_)
290	  {}
291	
292	  // Stats dump. Opt-in via VX_RTU_STATS env var (any non-empty
293	  // value). Prints to stderr at destruction so a smoke test that
294	  // wants observability can set the var on its `env` line. Silent
295	  // by default — most regression tests don't want the noise.
296	  ~Impl() {
297	    const char* env = std::getenv("VX_RTU_STATS");
298	    if (env == nullptr || env[0] == '\0') return;
299	    const auto& p = perf_stats_;
300	    std::fprintf(stderr, "[rtu-stats] rays_issued=%llu rays_hit=%llu rays_miss=%llu "
301	                         "mem_reads=%llu bvh_nodes=%llu bvh_leaves=%llu "
302	                         "instance_descents=%llu box_tests=%llu tri_tests=%llu "
303	                         "cb_ahs=%llu cb_chs=%llu cb_miss=%llu cb_is=%llu "
304	                         "reformation_yields=%llu coh_hits=%llu coh_misses=%llu "
305	                         "walker_cycles=%llu walker_busy_ticks=%llu\n",
306	                 (unsigned long long)p.rays_issued,
307	                 (unsigned long long)p.rays_hit,
308	                 (unsigned long long)p.rays_miss,
309	                 (unsigned long long)p.mem_reads,
310	                 (unsigned long long)p.bvh_nodes_fetched,
311	                 (unsigned long long)p.bvh_leaves_fetched,
312	                 (unsigned long long)p.bvh_instance_descents,
313	                 (unsigned long long)p.bvh_box_tests,
314	                 (unsigned long long)p.bvh_tri_tests,
315	                 (unsigned long long)p.ahs_callbacks,
316	                 (unsigned long long)p.chs_callbacks,
317	                 (unsigned long long)p.miss_callbacks,
318	                 (unsigned long long)p.is_callbacks,
319	                 (unsigned long long)p.reformation_yields,
320	                 (unsigned long long)p.coherency_hits,
321	                 (unsigned long long)p.coherency_misses,
322	                 (unsigned long long)p.walker_cycles_total,
323	                 (unsigned long long)p.walker_busy_ticks);
324	  }
325	
326	  void reset() {
327	    pool_.reset();
328	    mem_engine_.reset();
329	    reform_.reset();
330	    perf_stats_ = RtuCore::PerfStats();
331	    last_compute_signature_ = 0;
332	  }
333	
334	  void tick() {
335	    mem_engine_.drain_mem_rsp();
336	    drain_requests();
337	    mem_engine_.issue_memory();
338	    compute_intersections();
339	    reform_.tick();
340	    emit_completions();
341	  }
342	
343	  // Accept stage: drain at most one RtuReq from the per-core bus per
344	  // tick, round-robin across rtu_req_in[] channels (mirrors the OM /
345	  // DXA accept stages). Models a 1-deep arbiter with fair round-robin
346	  // channel service.
347	  void drain_requests() {
348	    auto& chs = simobject_->rtu_req_in;
349	    for (uint32_t i = 0; i < chs.size(); ++i) {
350	      uint32_t cid = (rr_req_ + i) % chs.size();
351	      auto& ch = chs.at(cid);
352	      if (ch.empty()) continue;
353	
354	      const RtuReq& req = ch.peek();
355	      if (req.kind == RtuReqKind::CB_ACTION) {
356	        // Per-lane CB_RET action. Each active lane in the packet
357	        // carries its own slot handle (cb_handle, written by SfuUnit
358	        // at process_cb_ret time from VX_RT_CB_HANDLE).
359	        // The gathered batch may have routed lanes from MULTIPLE
360	        // slots into one virtual warp, so we look each lane up by
361	        // handle and apply ACCEPT/IGNORE/TERMINATE on its own slot.
362	        for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
363	          if (((req.tmask_bits >> t) & 1u) == 0) continue;
364	          uint32_t handle = req.cb_handle[t];
365	          if (handle >= pool_.size()) continue;
366	          Slot& s = pool_.at(handle);
367	          if (!s.in_use || s.state != State::IN_QUEUE) continue;
368	          LaneState& l = s.lanes[t];
369	          if (!l.cb_pending) continue;
370	          uint32_t action = req.cb_action[t];
371	          if (action == VX_RT_CB_ACCEPT || action == VX_RT_CB_TERMINATE) {
372	            l.hit      = true;
373	            // A procedural (IS) accept commits the IS-computed hit_t
374	            // (read back from VX_RT_HIT_T into req.cb_hit_t); a triangle
375	            // AHS keeps the geometric candidate t.
376	            l.hit_t    = (l.cb_type == VX_RT_CB_TYPE_PROC)
377	                           ? req.cb_hit_t[t] : l.cand_t;
378	            l.hit_u    = l.cand_u;
379	            l.hit_v    = l.cand_v;
380	            l.hit_prim = l.cand_prim;
381	            l.hit_geometry = l.cand_geometry;
382	            // The accepted candidate's instance attributes (gl_InstanceID /
383	            // gl_InstanceCustomIndexEXT) become the committed hit's, so a
384	            // post-vx_rt_wait / CHS read reports the accepted instance.
385	            l.hit_instance_id     = l.cand_instance;
386	            l.hit_instance_custom = l.cand_custom;
387	            // The accepted candidate becomes the committed hit, so its
388	            // object-space ray is the committed one.
389	            l.hit_obj_o[0] = l.cand_obj_o[0];
390	            l.hit_obj_o[1] = l.cand_obj_o[1];
391	            l.hit_obj_o[2] = l.cand_obj_o[2];
392	            l.hit_obj_d[0] = l.cand_obj_d[0];
393	            l.hit_obj_d[1] = l.cand_obj_d[1];
394	            l.hit_obj_d[2] = l.cand_obj_d[2];
395	          }
396	          // VX_RT_CB_IGNORE: leave best_hit unchanged. Traversal is
397	          // single-yield-per-lane, so the slot transitions straight
398	          // to RESP (a richer multi-yield traversal would loop back
399	          // to COMPUTE for the lane's remaining candidates).
400	          //
401	          // VX_RT_CB_DONE: the CHS dispatcher has finished shading
402	          // the already-committed hit; no hit-state mutation, just
403	          // drain so the slot can transition to RESP.
404	          l.cb_pending = false;
405	          // If this was the last cb_pending lane in the slot, the
406	          // slot is fully resolved → RESP. Otherwise stay IN_QUEUE
407	          // for the next batched dispatch.
408	          bool any_pending = false;
409	          for (auto const& ll : s.lanes) {
410	            if (ll.cb_pending) { any_pending = true; break; }
411	          }
412	          if (!any_pending) s.state = State::RESP;
413	        }
414	        // Clear this warp's "callback in flight" gate so the next
415	        // queued CB_YIELD for the same warp (e.g. the second SBT
416	        // group in the divergent-SBT smoke) can be emitted.
417	        reform_.warp_cb_clear(req.warp_id);
418	        DT(3, "rtu-core cb_action applied (queue): tmask=0x"
419	              << std::hex << req.tmask_bits << std::dec);
420	        ch.pop();
421	        rr_req_ = (cid + 1) % chs.size();
422	        return;
423	      }
424	      // TRACE_NEW arrives with its slot pre-allocated by the
425	      // per-core RtuUnit (req.slot_idx). drain_requests just
426	      // populates the slot's req/lane state and lets the rest of
427	      // the FSM (issue_memory → compute → emit_completions) drive
428	      // it to terminal. The pool-full case is handled at TRACE
